 384	                    .orElseThrow(() -> new Xvt58Exception("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));
 385	
 386	
 387	            if (orderBid.getSale() != null) {
 388	                throw new Xmd85Exception("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
 389	            }
 390	
 391	
 392	            if (orderBid.getStatus() == Xtz73Status.MATCHED) {
 393	                throw new Xmd85Exception("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
 394	            }
 395	
 396	
 397	            if (orderBid.getOrder() != null) {
 398	                orderCommandService.deleteOrder(orderBid.getOrder().getId());
 399	            }
 400	
 401	
 402	            orderBidRepository.delete(orderBid);
